"use strict";
/* ai.js: AI training-data acquisition methods (family "ai") — pretraining crawls,
   corpus derivation, licensing, books, code, multimodal, speech, RLHF annotation,
   expert data, synthetic data, deployed-product user data, and rights clearance. */

M({
  id: "ai_crawl",
  family: "ai",
  name: "Pretraining web crawls (AI crawlers)",
  summary: "Operating a dedicated crawler fleet that fetches web pages at scale specifically to build raw text/HTML corpora for model pretraining, distinct from search-engine or archival crawling.",
  origins: ["o_platforms", "o_infra", "o_media"],
  ratings: {cost: 2, scale: 3, freshness: 2, moat: 1, legal: 2},
  steps: [
    "Register a distinct, documented user agent (e.g. `GPTBot`, `ClaudeBot`, `CCBot`, `Google-Extended`) and publish its purpose, contact details and the IP ranges it crawls from so site operators can identify and manage it.",
    "Parse `robots.txt` per host before every fetch, honoring `Disallow` rules scoped to your crawler's user-agent token, and cache the directive with a short TTL since sites change opt-outs frequently.",
    "Seed the frontier from a mix of prior crawl indexes (e.g. a Common Crawl URL list), sitemaps and outbound links discovered during the crawl; prioritize by domain diversity and estimated text quality rather than pure breadth.",
    "Run a distributed fetcher (e.g. Scrapy/Nutch-style workers behind a URL frontier queue) with per-domain rate limiting (politeness delay, concurrent-connection caps) to avoid degrading target sites.",
    "Render JavaScript-heavy pages selectively with a headless browser pool only where static HTML yields low text recall; budget this separately since it is far more expensive per page.",
    "Write raw responses to WARC files (request/response/metadata records) and derive WET (extracted plain text) files in the same pass so downstream corpus pipelines can consume either.",
    "Deduplicate at fetch time on URL-normalization and content hash to avoid re-storing mirrors and pagination variants.",
    "Respect HTTP 429/503 backoff and any published crawl-delay or pay-per-crawl signals (e.g. Cloudflare's crawler-permission headers) rather than retrying through them.",
    "Log coverage metrics per domain (pages fetched, bytes, language mix, error rate) and re-crawl high-value domains on a schedule rather than treating the crawl as one-shot.",
    "Maintain a global exclusion list fed by opt-out requests, legal takedowns and known spam/adult/low-quality domains, applied before the URL is even queued.",
  ],
  tools: ["Scrapy / Apache Nutch", "WARC/WET format (ia-web-archive libs)", "headless Chromium (Puppeteer/Playwright) for JS rendering", "robots.txt parser (Python `urllib.robotparser` or custom)", "URL frontier / dedup store (RocksDB, Redis)", "distributed job queue (Kafka, Celery)", "published crawler IP-range lists for self-identification"],
  economics: [
    "Cost drivers are bandwidth, storage of raw WARC (~petabytes at web scale) and headless-rendering compute, which dominates per-page cost when used.",
    "~tens of millions of USD per year (estimate) to run a crawler fleet and storage at frontier-lab scale; far cheaper (~low millions, estimate) to build a narrower domain-targeted crawl.",
    "Monetized indirectly: the crawl is an input asset to a trained model or licensed dataset, not sold directly.",
    "Moat is weak — crawling HTML is a commodity capability; the differentiator is downstream filtering quality (see ai_corpus), not the crawl itself.",
    "Build vs buy: most labs build their own crawler for control over scope and exclusion lists, but smaller players buy raw crawl data from Common Crawl rather than operate a fleet.",
  ],
  pitfalls: [
    "Crawler traps (infinite calendar/pagination URLs) waste frontier budget without added guardrails.",
    "Boilerplate, navigation chrome and ads dominate raw HTML and must be stripped downstream, not solved at crawl time.",
    "Paywalled and login-gated content yields truncated or teaser text that looks complete but isn't.",
    "Stale robots.txt caching can cause either over-crawling of newly-restricted sites or under-crawling of sites that lifted restrictions.",
  ],
  defenses: [
    "Sites block by user-agent string or published crawler IP ranges, or require JavaScript challenges that defeat non-rendering fetchers.",
    "robots.txt `Disallow` entries targeted at specific AI user agents (GPTBot, ClaudeBot, CCBot, Google-Extended) have become a standard opt-out mechanism.",
    "CDN/edge providers offer AI-crawler-specific blocking and metered 'pay-per-crawl' programs that charge per fetch instead of blocking outright.",
    "Honeypot links and canary text strings let site operators detect whether their content was ingested despite a block.",
  ],
  legal: [
    "robots.txt compliance is a voluntary technical norm, not itself a binding legal opt-out, but ignoring it strengthens unauthorized-access and breach-of-contract claims.",
    "Scraping publicly accessible pages generally falls outside US computer-misuse law per circuit case law, but authentication walls and explicit cease-and-desist notices change that analysis.",
    "Copyright claims attach to the stored text/HTML itself, independent of how it was fetched.",
  ],
  rules: ["g_robots", "g_cfaa", "g_copyright"],
  vendors: [
    {name: "OpenAI", note: "Operates the `GPTBot` crawler with a published user-agent string and documented IP ranges.", evidence: "public"},
    {name: "Anthropic", note: "Operates `ClaudeBot`, documented in its crawler policy.", evidence: "public"},
    {name: "Common Crawl Foundation", note: "Operates `CCBot`, a nonprofit general web crawl published monthly as open WARC/WET data.", evidence: "public"},
    {name: "Google", note: "Operates `Google-Extended`, a token that lets sites opt specifically out of Gemini/Vertex training use separate from search indexing.", evidence: "public"},
  ],
});

M({
  id: "ai_corpus",
  family: "ai",
  name: "Corpus derivation, filtering & deduplication",
  summary: "Turning raw crawl output (typically Common Crawl WARC/WET segments) into a cleaned, deduplicated, quality-filtered pretraining text corpus.",
  origins: ["o_platforms", "o_media", "o_infra"],
  ratings: {cost: 2, scale: 3, freshness: 1, moat: 2, legal: 2},
  steps: [
    "Pull WARC or pre-extracted WET segments from a crawl source (e.g. Common Crawl's S3 bucket, one monthly snapshot at a time) rather than re-crawling.",
    "Run language identification per document (e.g. fastText `lid.176`) and route documents into per-language shards, dropping languages below a confidence threshold.",
    "Extract main content from boilerplate HTML with a readability-style extractor (Trafilatura, jusText) when working from WARC rather than pre-stripped WET.",
    "Train or reuse a quality classifier (logistic regression or small transformer over n-gram/embedding features, as in C4/GPT-3's WebText filter) against a reference set of curated text (Wikipedia, books, edited journalism) and score every document.",
    "Deduplicate at document and paragraph granularity with MinHash LSH (as in CCNet/RefinedWeb) to remove near-duplicate boilerplate, templated pages and mirrored content; this is typically the single largest volume reduction step.",
    "Run PII filters (regex + NER for emails, phone numbers, government IDs) and toxicity/NSFW classifiers (e.g. Perspective API-style scoring) and either drop or down-weight flagged documents.",
    "Apply reference recipes rather than inventing filters from scratch — C4's heuristic+classifier filter, RefinedWeb's MacroData Refinement pipeline, FineWeb's quality-classifier-plus-dedup stack, or Dolma's modular toolkit are documented starting points.",
    "Decontaminate against known evaluation-benchmark text (n-gram overlap removal) before finalizing the corpus so benchmark scores aren't inflated by leakage.",
    "Shard the final corpus by language/domain/quality tier, store in a training-friendly format (tokenized shards, or raw text in Parquet/JSONL with provenance columns), and version every pipeline run so a given training snapshot is reproducible.",
    "Track per-stage yield (documents in vs. documents surviving each filter) to diagnose whether a filter is too aggressive or too permissive.",
  ],
  tools: ["CCNet pipeline", "fastText language ID", "Trafilatura / jusText extractors", "MinHash + datasketch LSH", "Dolma toolkit", "Perspective API-style toxicity scorer", "Presidio-style PII detector", "Parquet/JSONL with provenance metadata"],
  economics: [
    "Cost driver is compute for dedup and classification at crawl scale (billions of documents), typically run as large batch Spark/Ray jobs rather than per-document services.",
    "Filtering is lossy by design: refined corpora commonly retain well under half the raw crawl's documents by volume (recipe-dependent).",
    "Monetized as the training asset itself, or packaged and sold/open-released as a dataset product (e.g. as a `d_dataset` deliverable) to build reputation or ecosystem lock-in.",
    "Moat comes from filtering quality and proprietary quality-classifier training data, not from the underlying crawl, which multiple parties already share.",
    "Build vs buy: many teams start from an open derivative (FineWeb, Dolma, RefinedWeb) and customize filters rather than rebuilding the pipeline from raw WARC.",
  ],
  pitfalls: [
    "Quality classifiers trained against Wikipedia-like reference text systematically down-weight dialectal, informal and non-Western text, skewing the corpus.",
    "Aggressive MinHash thresholds can collapse legitimately distinct but templated content (e.g. product listings) into a single near-duplicate cluster.",
    "PII and toxicity filters trade recall for precision differently across languages, often performing worse on lower-resource languages.",
    "Insufficient decontamination against benchmark text silently inflates reported model evaluation scores.",
  ],
  defenses: [
    "Publishers embed canary strings or statistically unusual text in their pages specifically to detect downstream inclusion in training corpora via membership-inference probing of released models.",
    "Licensing terms attached to crawl-derivative datasets (e.g. research-only clauses) constrain commercial reuse of the filtered corpus itself.",
  ],
  legal: [
    "The filtering pipeline does not change the copyright status of the underlying text; downstream training-data copyright suits (e.g. the New York Times v. OpenAI and author class actions against multiple labs) target this stage's output as much as the raw crawl.",
    "Jurisdictions with a text-and-data-mining exception (EU Art. 4 CDSM Directive) make TDM-purpose filtering lawful subject to a rights-holder opt-out, which the corpus pipeline must be able to honor.",
  ],
  rules: ["g_copyright", "g_robots"],
  vendors: [
    {name: "Common Crawl Foundation", note: "Publishes the raw WARC/WET/WAT source most third-party pretraining corpora derive from.", evidence: "public"},
    {name: "Allen Institute for AI", note: "Publishes the Dolma corpus and toolkit documenting its filtering and dedup recipe.", evidence: "public"},
    {name: "Hugging Face", note: "Publishes FineWeb with a documented quality-filtering and dedup pipeline over Common Crawl.", evidence: "public"},
    {name: "TII", note: "Published the RefinedWeb corpus and its MacroData Refinement filtering recipe (used for the Falcon models).", evidence: "public"},
  ],
});

M({
  id: "ai_license",
  family: "ai",
  name: "Content licensing deals",
  summary: "Negotiating direct commercial agreements with platforms and publishers for ongoing or historical access to content for AI training, as an alternative or supplement to crawling.",
  origins: ["o_platforms", "o_media", "o_commerce"],
  ratings: {cost: 3, scale: 2, freshness: 3, moat: 3, legal: 1},
  steps: [
    "Identify content categories the crawl can't adequately cover: real-time social/forum data, paywalled news archives, stock imagery with clean rights, or structured Q&A data.",
    "Approach the rights holder (platform or publisher) to negotiate a data-access agreement covering historical archive access plus an ongoing feed, rather than a one-time dump.",
    "Structure the deal commercially as either a flat licensing fee, a per-volume/per-token rate, or a revenue-share/partnership arrangement, with the rights holder retaining the right to audit usage.",
    "Require contractual warranties on chain-of-title (the publisher actually owns or has cleared rights to the content it's licensing) and indemnification if third-party content is embedded (e.g. user-submitted images within a forum post).",
    "Define scope precisely in the contract: which content types, date ranges, geographies and derivative-model uses are covered, since broad licenses are far more expensive than narrow ones.",
    "Build an ingestion pipeline against the publisher's delivery mechanism (bulk SFTP export, dedicated API, or direct database replication) rather than scraping the same content you're now licensed to receive.",
    "Tag ingested content with licensing provenance metadata so it can be included or excluded from specific training runs per the contract's scope and term.",
    "Track renewal and termination clauses; licensed feeds typically have multi-year terms with volume-based reconciliation and exclusivity or most-favored-terms clauses.",
  ],
  tools: ["data-licensing agreement templates", "SFTP/bulk-export delivery pipelines", "publisher APIs (e.g. a news wire feed)", "rights/provenance metadata tagging (IPTC-style)", "revenue-share reconciliation/audit tooling"],
  economics: [
    "Cost driver is negotiated fee structure, often a mix of upfront payment and ongoing per-period or per-volume fee; multi-year news and platform deals have been reported in the tens of millions of USD per year (estimate, deal-specific).",
    "Monetized by the licensor as a new revenue line from content that was previously unmonetized for this purpose; monetized by the licensee as litigation-risk reduction plus guaranteed fresh/structured access.",
    "Moat is strong when the deal is exclusive — a competitor literally cannot obtain the same licensed feed.",
    "Build vs buy: licensing is the 'buy' alternative to the legal risk and incompleteness of crawling the same content; large labs pursue both in parallel for different content classes.",
    "Pricing power sits with rights holders that have unique, high-quality, hard-to-scrape content (Reddit's real-time conversational data, wire-service news).",
  ],
  pitfalls: [
    "A licensed feed only covers what the contract scopes; teams often still need crawl or other sourcing to fill gaps.",
    "Warranty gaps are common — a publisher's licensed archive can still contain third-party-owned embedded content it didn't fully clear.",
    "Exclusivity clauses that help the licensee can simultaneously block other data-acquisition routes (e.g. the platform then blocking other crawlers from the same content).",
  ],
  defenses: [
    "Rights holders that strike an exclusive deal often simultaneously block or rate-limit non-partner crawlers from the same content, as reported after some platform-AI licensing agreements.",
    "Publishers use litigation threats and DMCA takedowns as negotiating leverage prior to or instead of a licensing deal.",
  ],
  legal: [
    "A properly licensed deal sidesteps copyright infringement exposure for the covered content, which is the primary reason labs pursue it despite the cost.",
    "Chain-of-title warranties and indemnification clauses are the main legal protection against licensing content the publisher didn't actually have full rights to.",
    "Licensing deals are themselves contracts governed by ordinary contract law disputes over scope and renewal, separate from copyright exposure.",
  ],
  rules: ["g_copyright", "g_provenance", "g_contract"],
  vendors: [
    {name: "Reddit", note: "Reported data-licensing agreement with Google covering real-time access to Reddit content for training/retrieval.", evidence: "reported"},
    {name: "News Corp", note: "Reported multi-year content-licensing agreement with OpenAI.", evidence: "reported"},
    {name: "Axel Springer", note: "Reported licensing partnership with OpenAI covering news content.", evidence: "reported"},
    {name: "Associated Press", note: "Reported licensing agreement with OpenAI for its news archive.", evidence: "reported"},
    {name: "Shutterstock", note: "Reported multi-year image/data licensing agreements with multiple AI labs.", evidence: "reported"},
  ],
});

